const jobs = $input.all()[0].json;

// Group by section
const sections = {};
jobs.forEach(job => {
  if (!sections[job.section]) {
    sections[job.section] = [];
  }
  sections[job.section].push(job);
});

// Calculate totals
const totalJobs = jobs.length;
const doneJobs = jobs.filter(j => j.status === 'done').length;
const remainingJobs = totalJobs - doneJobs;
const progressPct = Math.round((doneJobs / totalJobs) * 100);

// Calculate spend
const estimatedSpend = jobs.reduce((sum, j) => {
  const avg = ((parseFloat(j.cost_low) || 0) + (parseFloat(j.cost_high) || 0)) / 2;
  return sum + avg;
}, 0);

// Top 3 Ben jobs
const benJobs = jobs.filter(j => j.who === 'ben' && j.status === 'not_started')
  .slice(0, 3)
  .map(j => `• ${j.title}`);

// Build message
const launchDate = new Date('2026-06-07');
const today = new Date();
const daysToLaunch = Math.ceil((launchDate - today) / (1000 * 60 * 60 * 24));

let message = `🏠 *Forge House Jobs Digest*\n\n`;
message += `📊 Progress: ${doneJobs}/${totalJobs} done (${progressPct}%)\n`;
message += `⏰ Launch: ${daysToLaunch} days (7 Jun 2026)\n`;
message += `💰 Est. remaining spend: £${Math.round(estimatedSpend)}\n\n`;

for (const [section, sectionJobs] of Object.entries(sections)) {
  const done = sectionJobs.filter(j => j.status === 'done').length;
  message += `*${section}*: ${done}/${sectionJobs.length} done\n`;
}

if (benJobs.length > 0) {
  message += `\n*This week's Ben jobs:*\n${benJobs.join('\n')}\n`;
}

message += `\n_Open JARVIS → Forge → House Jobs for details_`;

return [{ json: { message } }];
